<?php
declare(strict_types=1);
require_once __DIR__.'/../cutting.php';require_once __DIR__.'/goal.php';require_once __DIR__.'/../ai/insights.php';
const CUTTING_AGENT_MANIFEST='cutting-agent-20261025.2-general-fund';
const CUTTING_AGENT_METRICS=['demand_quantity','produced_quantity','deficit','extra','meters_mm','seconds','labor_seconds','fund_cents','material_cents'];
function cutting_aiAction(string $action,array $input):array{
 $c=permit(['owner','technologist','chief','foreman']);manufacturingRequireStorage();
 if($action==='cutting_ai_start'){
  $record=cuttingRecord($c,textField($input,'cutting_id',32,true));checkRevision($record['revision'],$input);$o=orderRecord($record['order_id']);$o['route']=decode($o['route']);$assets=cuttingAssets($c);$fresh=cuttingCalculate($record['state'],$c,$o,$assets,$record['id']);if(($record['calculation']['input_versions']??[])!==$fresh['input_versions'])fail('Основа расчёта изменилась. Сохраните черновик перед анализом.',409);
  foreach(rows("SELECT * FROM assistant_jobs WHERE company_id=? AND actor_id=? AND kind='cutting' ORDER BY created_at DESC LIMIT 15",[$c['id'],$_SESSION['user_id']]) as $prior){$old=decode($prior['input_json']);if(($old['record']['id']??'')===$record['id']&&($old['record']['revision']??-1)===$record['revision']&&($old['record']['calculation']['input_versions']??[])===$fresh['input_versions'])return $c['role']==='owner'?workflowPublic($prior):cuttingRedact(workflowPublic($prior));}
  $capture=['now'=>time(),'busy'=>cuttingBusy($c,$record['id']),'roll_used'=>cuttingRollUsed($c,$record['id']),'remaining'=>cuttingRemaining($c,$o,$record['id']),'preparation_balances'=>preparationBalances($c,$o),'credits'=>cuttingCredits($c,$o,$record['state']['demand'],$record['id']),'resource_hash'=>$fresh['input_versions']['resource_hash']];$c['_preparation_records']=[$o['id']=>preparationRecord($c,$o)];$c['_cutting_capture']=$capture;$job=workflowCreate('cutting',['manifest'=>CUTTING_AGENT_MANIFEST,'record'=>$record,'order'=>$o,'company'=>$c,'assets'=>$assets],['part'=>0,'total'=>4,'options'=>[]],textField($input,'key',100,true));return $c['role']==='owner'?workflowPublic($job):cuttingRedact(workflowPublic($job));
 }
 $id=textField($input,'id',32,true);$job=workflowRecord($id);if($job['kind']!=='cutting')fail('Это другое задание помощника',409);
 $result=workflowStep($id,function(array $job){$in=decode($job['input_json']);$p=decode($job['progress_json']);$part=(int)$p['part'];$strategies=['fast'=>'Быстрый запуск','economical'=>'Экономный расход','balanced'=>'Сбалансированный'];
  if($part<3){$strategy=array_keys($strategies)[$part];$state=cuttingPropose($in['record']['state'],$in['company'],$in['order'],$in['assets'],$strategy);$calc=cuttingCalculate($state,$in['company'],$in['order'],$in['assets'],$in['record']['id'],$strategy);$p['options'][]=['name'=>$strategies[$strategy],'strategy'=>$strategy,'state'=>$state,'calculation'=>$calc];$p['part']=$part+1;return ['ready'=>false,'progress'=>$p];}
  // Only numeric, enumerated projections leave this server. No labels, documents,
  // company/person IDs, names, raw errors or imported text enter the AI prompt.
  $safe=[];foreach($p['options'] as $option){$calc=$option['calculation'];$row=['strategy'=>$option['strategy'],'status'=>$calc['status'],'demand_quantity'=>$calc['demand_quantity'],'produced_quantity'=>$calc['produced_quantity'],'deficit'=>$calc['deficit'],'extra'=>$calc['extra'],'meters_mm'=>$calc['meters_mm'],'seconds'=>$calc['seconds'],'labor_seconds'=>$calc['labor_seconds'],'error_codes'=>array_values(array_unique(array_column($calc['errors'],'code')))];if($in['company']['role']==='owner')$row+=['fund_cents'=>$calc['pay']['fund_cents'],'material_cents'=>$calc['material_cents']];$safe[]=$row;}
  $reply=aiGateway([],['_messages'=>insightMessages('Сравни рассчитанные варианты раскроя. Общий фонд единственный, личных начислений нет. Сначала физическая допустимость и обеспечение сроков, затем расход и деньги. Сохранение черновика не выпускает задания.',['variants'=>$safe],CUTTING_AGENT_METRICS),'_validator'=>fn($text)=>insightReply($text,CUTTING_AGENT_METRICS),'_prompt_version'=>CUTTING_AGENT_MANIFEST]);$p['part']=4;return ['ready'=>true,'progress'=>['part'=>4,'total'=>4],'model'=>$reply['model'],'result'=>['manifest'=>CUTTING_AGENT_MANIFEST,'cutting_id'=>$in['record']['id'],'cutting_revision'=>$in['record']['revision'],'input_versions'=>$in['record']['calculation']['input_versions']??[],'options'=>$p['options'],'insights'=>$reply['data'],'notice'=>'Выберите вариант для нового черновика. Утверждение норм и выпуск — отдельные действия человека.']];
 });return $c['role']==='owner'?$result:cuttingRedact($result);
}
